# -- Supersession chains over cross-site chain fork aggregate decision --------
# -- aggregates ----------------------------------------------------------------
#
# This layer mirrors the chain fork aggregate chain (``cfca``) layer but its
# root is an :func:`aggregate_chain_fork_aggregate_decisions` packet and its
# increment decisions are :func:`adjudicate_chain_fork_aggregate_proofs`
# rulings: the two invariant policies are the original ``{"batch", "sites",
# "threshold"}`` prune policy and the site authorization policy, and the
# counted declarations keep the non-positional proof summary ordering of that
# root (only the proof digest multiset must agree).  Only the **decision** site
# policy may rotate.  Successor and chain-binding faults reuse the prune
# aggregate hierarchy (InvalidAggregateChainError), anchor faults reuse
# InvalidAggregateAnchorError, and a malformed root remains an
# InvalidChainForkDecisionAggregateError.

DECISION_AGGREGATE_CHAIN_VERSION = 1
DECISION_AGGREGATE_CHAINS_VERSION = 1

