def _dac_chain_invalid(message: str) -> InvalidAggregateChainError:
    return InvalidAggregateChainError(
        f"invalid decision aggregate chain: {message}"
    )


def _dac_anchor_invalid(message: str) -> InvalidAggregateAnchorError:
    return InvalidAggregateAnchorError(
        f"invalid decision aggregate anchor: {message}"
    )


def _reject_duplicate_dac_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate successor keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _dac_chain_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


def _reject_duplicate_dac_anchor_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate anchor keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _dac_anchor_invalid(f"duplicate key {key!r} in object")
        result[key] = value
